mapper.select:
select
DATE_FORMAT(F.PZ_DATE,'%c') pzDateMonth, IFNULL(B.MD,'0') md, IFNULL(B.MC,'0') mc, IFNULL(S.QCMD,'0') qcmd, IFNULL(S.QCMC,'0') qcmc,
TO_NUMBER(TO_CHAR(F.PZ_DATE,'MM')) pzDateMonth, NVL(B.MD,'0') md, NVL(B.MC,'0') mc, NVL(S.QCMD,'0') qcmd, NVL(S.QCMC,'0') qcmc,
C.ACCID accId, C.ACCNAME1 accAllName, F.PZ_DATE pzDate, B.LINETEXT lineText, C.DC dc, F.PZH pzh, S.QMDC qmdc, S.BQMD bqmd, S.BQMC bqmc, S.LJMD ljmd, S.LJMC ljmc, S.QMMC qmmc, S.QMMD qmmd, S.QCDC qcdc, B.ENTRYID entryId FROM ${dbSource}.TBL_ACC_BSEG${year} B LEFT JOIN ${dbSource}.TBL_ACC_BKPF F ON F.GLH = B.GLH AND F.AYEAR = B.AYEAR LEFT JOIN ${dbSource}.TBL_ACCOUNT C ON B.ACCID= C.ACCID AND B.AYEAR = C.AYEAR LEFT JOIN ${dbSource}.TBL_ACC_SUM S ON B.ACCID = S.ACCID AND B.AYEAR = S.AYEAR AND B.AMONTH = S.AMONTH WHERE B.ACCID = #{ACCID}
ORDER BY ${orderByClause}

SELECT
C.ACCID as accid, B.LINETEXT as lineText,
NVL(B.MD, '0') as md, NVL(B.MC, '0') as mc,C.ACCNAME1 as accName, C.DC as dc, F.PZH as pzh,
TO_CHAR(F.PZ_DATE, 'yyyy-MM-dd') as pzDate, NVL (S.QCMD, '0') as qcmd, NVL (S.QCMC, '0') as qcmc,
S.QMDC as qmdc, S.BQMD as bqmd, S.BQMC as bqmc,
S.LJMD as ljmd, S.LJMC as ljmc, S.QMMC as qmmc, S.QMMD as qmmd, S.QCDC as qcdc,B.ENTRYID as entryId,B.AMONTH AS AMONTH,B.GLH AS GLH
FROM ${dbSource}.TBL_ACC_BSEG${bookYear} B
LEFT JOIN ${dbSource}.TBL_ACC_BKPF F ON F.GLH = B.GLH AND F.AYEAR = B.AYEAR
LEFT JOIN ${dbSource}.TBL_ACCOUNT C ON B.ACCID = C.ACCID AND B.AYEAR = C.AYEAR
LEFT JOIN ${dbSource}.TBL_ACC_SUM S ON B.ACCID = S.ACCID AND B.AYEAR = S.AYEAR AND B.AMONTH = S.AMONTH
WHERE 1=1

    AND B.ACCID = #{accid}



        AND C.ACCNAME1 LIKE '%${accNameOne}%'


        AND C.ACCNAME1 not LIKE '%${accNameOne}%'


        AND C.ACCNAME1  #{accNameOne}




        AND B.LINETEXT LIKE '%${lineText}%'


        AND B.LINETEXT not LIKE '%${lineText}%'


        AND B.LINETEXT  #{lineText}



    AND TO_CHAR(F.PZ_DATE, 'yyyy-MM-dd')   #{pzDate}


    AND B.MD  #{md}


    AND B.MC  #{mc}


    AND B.AMONTH >= #{minMonth}
    AND B.AMONTH  <=   #{maxMonth}

ORDER BY F.PZ_DATE ASC,F.PZH ASC,B.ENTRYID ASC

SELECT
COUNT (0)
FROM
${dbSource}.TBL_ACC_BSEG${bookYear} B
LEFT JOIN ${dbSource}.TBL_ACC_BKPF F ON F.GLH = B.GLH AND F.AYEAR = B.AYEAR
LEFT JOIN ${dbSource}.TBL_ACCOUNT C ON B.ACCID = C.ACCID AND B.AYEAR = C.AYEAR
LEFT JOIN ${dbSource}.TBL_ACC_SUM S ON B.ACCID = S.ACCID AND B.AYEAR = S.AYEAR AND B.AMONTH = S.AMONTH
WHERE 1=1

    AND B.ACCID = #{accid}



        AND C.ACCNAME1 LIKE '%${accNameOne}%'


        AND C.ACCNAME1 not LIKE '%${accNameOne}%'


        AND C.ACCNAME1  #{accNameOne}




        AND B.LINETEXT LIKE '%${lineText}%'


        AND B.LINETEXT not LIKE '%${lineText}%'


        AND B.LINETEXT  #{lineText}



    AND TO_CHAR(F.PZ_DATE, 'yyyy-MM-dd')   #{pzDate}


    AND NVL(B.MD,'0')  #{md}


    AND NVL(B.MC,'0')  #{mc}


    AND B.AMONTH >= #{minMonth}
    AND B.AMONTH  <=   #{maxMonth}

SELECT * FROM ( SELECT C.* FROM ${dbSource}.TBL_ACC_BSEG${bookYear} B LEFT JOIN ${dbSource}.TBL_ACCOUNT C ON B.ACCID = C.ACCID AND B.AYEAR = C.AYEAR LEFT JOIN ${dbSource}.TBL_ACC_BKPF F ON F.GLH = B.GLH AND F.AYEAR = B.AYEAR WHERE F.AYEAR = #{bookYear} AND C.ISDCACC = 1
and F.AMONTH >= #{minMonth}
AND F.AMONTH <= #{maxMonth}
AND C.ACCID = '${accid}'
ORDER BY C.ACCID,F.PZ_DATE) T1 WHERE ROWNUM = 1

SELECT C.ACCID as accid, B.LINETEXT as lineText,B.GLH AS GLH, NVL (B.MD, '0') AS md, NVL (B.MC, '0') AS mc, C.ACCNAME1 as accName, C.DC as dc, F.PZH as pzh, TO_CHAR(F.PZ_DATE, 'yyyy-MM-dd') as pzDate,B.ENTRYID AS entryId, NVL (S.QCMD, '0') AS qcmd, NVL (S.QCMC, '0') AS qcmc, NVL (S.QMDC, '0') AS qmdc, NVL (S.BQMD, '0') AS bqmd, NVL (S.BQMC, '0') AS bqmc, NVL (S.LJMD, '0') AS ljmd, NVL (S.LJMC, '0') AS ljmc, NVL (S.QMMC, '0') AS qmmc, NVL (S.QMMD, '0') AS qmmd, NVL (S.QCDC, '0') AS qcdc, TO_NUMBER (TO_CHAR(F.PZ_DATE, 'dd')) AS dayNo,TO_NUMBER (TO_CHAR(F.PZ_DATE, 'MM')) AS amonth FROM ${dbSource}.TBL_ACC_BSEG${bookYear} B LEFT JOIN ${dbSource}.TBL_ACC_BKPF F ON F.GLH = B.GLH AND F.AYEAR = B.AYEAR LEFT JOIN ${dbSource}.TBL_ACCOUNT C ON B.ACCID = C.ACCID AND B.AYEAR = C.AYEAR LEFT JOIN ${dbSource}.TBL_ACC_SUM S ON S.AYEAR = B.AYEAR AND S.ACCID = B.ACCID AND S.AMONTH = B.AMONTH WHERE F.AYEAR = '${bookYear}'
AND TO_CHAR(F.PZ_DATE, 'MM') >= #{minMonth} AND TO_CHAR(F.PZ_DATE, 'MM') <= #{maxMonth}
and F.PZH LIKE '%${pzh}%'
and F.PZH not LIKE '%${pzh}%'
and F.PZH
#{pzh}
AND B.ACCID = #{accid}
AND C.ACCNAME1 LIKE '%${accNameOne}%'
AND C.ACCNAME1 not LIKE '%${accNameOne}%'
AND C.ACCNAME1
#{accNameOne}
AND B.LINETEXT LIKE '%${lineText}%'
AND B.LINETEXT not LIKE '%${lineText}%'
AND B.LINETEXT
#{lineText}
AND NVL(B.MD,'0')
#{md}
AND NVL(B.MC,'0')
#{mc}
AND F.PZ_DATE
TO_DATE(#{pzDate},'yyyy-MM-dd')
ORDER BY F.PZ_DATE ASC,F.PZH ASC,B.ENTRYID ASC

SELECT COUNT (0) FROM ${dbSource}.TBL_ACC_BSEG${bookYear} B
LEFT JOIN ${dbSource}.TBL_ACC_BKPF F ON F.GLH = B.GLH AND F.AYEAR = B.AYEAR
LEFT JOIN ${dbSource}.TBL_ACCOUNT C ON B.ACCID = C.ACCID AND B.AYEAR = C.AYEAR
LEFT JOIN ${dbSource}.TBL_ACC_SUM S ON S.AYEAR = B.AYEAR AND S.ACCID = B.ACCID AND S.AMONTH = B.AMONTH
WHERE F.AYEAR LIKE '%${bookYear}%'

    AND TO_CHAR(F.PZ_DATE, 'MM') >= #{minMonth}
    AND TO_CHAR(F.PZ_DATE, 'MM')  <   #{maxMonth}


    AND B.ACCID = #{accid}



        and F.PZH LIKE '%${pzh}%'


        and F.PZH not LIKE '%${pzh}%'


       	and F.PZH

    	#{pzh}




        AND C.ACCNAME1 LIKE '%${accNameOne}%'


        AND C.ACCNAME1 not LIKE '%${accNameOne}%'


        AND C.ACCNAME1

        #{accNameOne}




        AND B.LINETEXT LIKE '%${lineText}%'


        AND B.LINETEXT not LIKE '%${lineText}%'


        AND B.LINETEXT

        #{lineText}



    AND NVL(B.MD,'0')

    #{md}


    AND NVL(B.MC,'0')

    #{mc}


    AND F.PZ_DATE

    TO_DATE(#{pzDate},'yyyy-MM-dd')

SELECT NVL(SUM(B.MD),0) AS MD,NVL(SUM(B.MC),0) AS MC 
FROM ${dbSource}.TBL_ACC_BSEG${bookYear} B
LEFT JOIN ${dbSource}.TBL_ACC_BKPF F ON F.GLH = B.GLH AND F.AYEAR = B.AYEAR 
WHERE B.AMONTH = #{month} AND B.ACCID = #{accid} 
AND F.PZ_DATE = #{pzDate}
